-- Preserve system_run category identity; align its parent category label with the source workbook.

UPDATE metric_category SET category_name='运行效率',description='运行效率大类；包含原系统运行的系统性能、系统异常及梳理表绿色指标',update_time=NOW() WHERE category_code='system_run';

UPDATE `alarm` SET category_name='运行效率' WHERE category_name='系统运行';

UPDATE `category_health_history` SET category_name='运行效率' WHERE category_name='系统运行';

UPDATE `dashboard_view_config` SET category_name='运行效率' WHERE category_name='系统运行';

UPDATE `health_snapshot_1d` SET category_name='运行效率' WHERE category_name='系统运行';

UPDATE `health_snapshot_1h` SET category_name='运行效率' WHERE category_name='系统运行';

UPDATE `health_snapshot_30d` SET category_name='运行效率' WHERE category_name='系统运行';

UPDATE `health_snapshot_6h` SET category_name='运行效率' WHERE category_name='系统运行';

UPDATE `health_snapshot_7d` SET category_name='运行效率' WHERE category_name='系统运行';

UPDATE `issue` SET category_name='运行效率' WHERE category_name='系统运行';

UPDATE `metric_health_history` SET category_name='运行效率' WHERE category_name='系统运行';

UPDATE `metric_value_history` SET category_name='运行效率' WHERE category_name='系统运行';

UPDATE `sub_category_health_history` SET category_name='运行效率' WHERE category_name='系统运行';

UPDATE alarm_strategy s JOIN metric_category c ON s.target_type='category' AND s.target_id=c.id SET s.target_name='运行效率',s.strategy_name=REPLACE(s.strategy_name,'系统运行','运行效率') WHERE c.category_code='system_run';


































































SELECT m.id,NULL,NULL,0,NULL,NULL,0,NULL FROM metric_item m JOIN metric_category c ON c.id=m.category_id
WHERE c.category_code='system_run' AND m.metric_code LIKE 'EFF\_GREEN\_%'
ON DUPLICATE KEY UPDATE alarm_threshold=NULL,alarm_condition=NULL,alarm_status=0,gongdan_threshold=NULL,gongdan_condition=NULL,gongdan_status=0;

SELECT CONCAT('指标阈值-',m.metric_name),'metric','metric',m.id,m.metric_name,0,NULL,NULL,0,NULL,NULL,0,NOW(),NOW()
FROM metric_item m JOIN metric_category c ON c.id=m.category_id
WHERE c.category_code='system_run' AND m.metric_code LIKE 'EFF\_GREEN\_%'
AND NOT EXISTS(SELECT 1 FROM alarm_strategy s WHERE s.target_type='metric' AND s.target_id=m.id);
